const placeOrder=async()=>{if(!name.trim())return notify('Add your name first');if(type==='DINE_IN'&&!table)return notify('Scan your table QR code to select a dine-in table automatically.');let createdOrder:Order|null=null;setLoading(true);try{const o=await request('/api/orders',{method:'POST',body:JSON.stringify({customerName:name.trim(),paymentMethod,type,tableLabel:table||undefined,notes:notes||undefined,couponCode:coupon||undefined,items:cart.map(x=>({variantId:x.variant.id,quantity:x.qty}))})});createdOrder=o;setLastOrderId(o.id);setBotOrderId(o.id);sessionStorage.setItem('tf-order-id',o.id);let historySaved=true;try{saveCustomerOrderId(o.id)}catch(e){historySaved=false;console.error('Could not save customer order history',e)};if(paymentMethod==='RAZORPAY'){if(!historySaved)notify('Order placed, but this browser could not save it to your order history');setCart([]);await startRazorpayCheckout(o);return}setOrder(o);setCart([]);setCheckout(false);setDrawer(false);notify(historySaved?'Order sent to the kitchen':'Order sent, but this browser could not save it to your order history')}catch(e:any){if(createdOrder&&paymentMethod==='RAZORPAY'){setOrder(createdOrder);setCart([]);setCheckout(false);setDrawer(false);notify('Order #'+createdOrder.orderNumber+' was saved, but payment could not start: '+e.message+'. Retry from the order details.')}else notify(apiDown?'Connect the API and database to place orders':e.message)}finally{setLoading(false)}};
